    const { path, query } = splitUrl(c.req.url.replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/, ''));
    const out = await handler({
      method: c.req.method,
      path,
      query,
      headers: c.req.header(),
      text: () => c.req.text(),
      raw: c,
    });
